const campaigns=[{name:'AI Search',sub:'Visibility campaign',people:[47,49,12],count:'+32',progress:96,date:'7 Oct 2026',score:'4.8'},{name:'SEO Content',sub:'Content optimization',people:[13,44,25],count:'+6',progress:24,date:'4 Oct 2026',score:'4.4'},{name:'Local SEO',sub:'Google Business Profile',people:[12,47,49],count:'+15',progress:46,date:'26 Sep 2026',score:'5.0'}];
const channels=[['Google Search',4.9],['ChatGPT',4.4],['Perplexity',3.9],['Google AI',3.5],['Claude',1.8],['Gemini',.9]];
const escapeHTML=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const avatars=(ids,count)=>`<div class="avatars">${ids.map(id=>`<img src="https://i.pravatar.cc/48?img=${id}" alt="" loading="eager" onerror="this.style.visibility='hidden'">`).join('')}</div><span>${count}</span>`;
function renderCampaigns(query=''){const visible=campaigns.filter(c=>(c.name+' '+c.sub+' Alan').toLowerCase().includes(query.toLowerCase()));document.querySelector('#campaign-rows').innerHTML=visible.map(c=>`<tr class="campaign-row" tabindex="0" role="button" aria-label="View ${escapeHTML(c.name)} campaign" data-campaign="${escapeHTML(c.name)}"><td><strong>${escapeHTML(c.name)}</strong><small>${escapeHTML(c.sub)}</small></td><td><div class="avatar-count">${avatars(c.people,c.count)}</div></td><td><div class="progress-cell"><div class="segmented" aria-hidden="true">${Array.from({length:12},(_,i)=>`<i class="${i<Math.round(c.progress/100*12)?'filled':''}"></i>`).join('')}</div><b>${c.progress}%</b></div></td><td>${c.date}</td><td><div class="score"><i class="medal" aria-hidden="true"></i>${c.score}</div></td></tr>`).join('');document.querySelector('.empty').hidden=visible.length>0;document.querySelectorAll('[data-campaign]').forEach(row=>{row.onclick=()=>showCampaign(row.dataset.campaign);row.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();showCampaign(row.dataset.campaign)}}})}
renderCampaigns();document.querySelectorAll('[data-avatars]').forEach(el=>el.innerHTML=avatars(el.dataset.avatars.split(','),el.dataset.count));
document.querySelector('#performance-bars').innerHTML=channels.map(([name,n],i)=>`<div class="performance-row"><div><span>${name}</span><b>${n.toFixed(1)}</b></div><div class="performance-track" role="meter" aria-label="${name}" aria-valuemin="0" aria-valuemax="5" aria-valuenow="${n}"><i style="--value:${n/5*94}%;animation-delay:${i*40}ms"></i></div></div>`).join('');
let offset=0;const circumference=2*Math.PI*101;document.querySelector('#donut-segments').innerHTML=[['#d998e6',16],['#029bd1',37],['#90d698',61],['#ff9d9a',28],['#ffd181',12]].map(([color,count])=>{const sweep=count/154*circumference;const length=sweep-11;const markup=`<circle class="donut-segment" cx="125" cy="125" r="101" stroke="${color}" stroke-dasharray="${length} ${circumference-length}" transform="rotate(${offset/circumference*360} 125 125)"/>`;offset+=sweep;return markup}).join('');
document.querySelector('#histogram-bars').innerHTML=[7,7,7,8,10,14,19,44,28,48,60,48,28,18,11,8,7,7].map((height,i)=>`<i class="${i>=7&&i<=12?'lit':''}" style="--height:${height}px;animation-delay:${i*22}ms"></i>`).join('');
const dialog=document.querySelector('#detail-dialog'),content=document.querySelector('#dialog-content');let toastTimer;function toast(text){const el=document.querySelector('#toast');el.textContent=text;el.classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('visible'),3200)}
function openDialog(title,html){document.querySelector('#dialog-title').textContent=title;content.innerHTML=html;if(!dialog.open)dialog.showModal()}
function lines(items){return items.map(([label,value])=>`<div class="detail-line"><span>${escapeHTML(label)}</span><strong>${escapeHTML(value)}</strong></div>`).join('')}
const demo='<p class="detail-intro">Sample workspace data for the Uplift AI first draft.</p>';
function showCampaign(name){const c=campaigns.find(c=>c.name===name);openDialog(c.name,demo+lines([['Focus',c.sub],['Progress',c.progress+'%'],['Due date',c.date],['Quality score',c.score+' / 5'],['Owner','Alan Miller']])+`<button class="primary-button" id="campaign-export">Download campaign report</button>`);document.querySelector('#campaign-export').onclick=()=>downloadCSV(c.name,[['Campaign','Progress','Due date','Score'],[c.name,c.progress,c.date,c.score]])}
function showDetails(type){if(type==='campaigns'){openDialog('Active SEO campaigns',demo+lines(campaigns.map(c=>[c.name,c.progress+'% complete']))+'<button class="primary-button" id="add-campaign">Create campaign</button>');document.querySelector('#add-campaign').onclick=createCampaign;return}const sections={visibility:['Growth status overview',[['Tracked keywords','154'],['Gaining visibility','129 (84%)'],['Needs attention','25'],['Rank 1–3','37'],['Rank 4–10','16'],['Rank 11–20','61'],['Rank 21–50','28'],['Unranked','12']]],channels:['Channel performance',channels.map(([name,n])=>[name,n.toFixed(1)+' / 5'])],traffic:['Traffic overview',[['Total visits','24,350'],['Monthly growth','+1,260'],['Organic search','8,500'],['Direct referrals','7,792'],['AI referrals','4,708'],['Combined referrals','12,500'],['Local search','3,350']]],publishing:['Publishing activity',[['Published this month','38 assets'],['Prior comparison period','22 assets'],['Month-over-month growth','73%'],['Next publication','26 Sep 2026']]],team:['Your team',[['Alan Miller','Workspace owner'],['Sarah Chen','SEO strategist'],['James Wilson','Content editor'],['Maya Patel','AI visibility analyst']]],integrations:['Connected apps',[['Google Search Console','Demo connection'],['Google Analytics','Demo connection'],['Google Business Profile','Demo connection'],['Microsoft Teams','Demo connection']]],profile:['Alan Miller',[['Workspace','Uplift AI'],['Role','Workspace owner'],['Environment','Demo workspace']]]};const section=sections[type];if(section)openDialog(section[0],demo+lines(section[1]));}
function createCampaign(){openDialog('Create a campaign','<p class="detail-intro">Add a campaign to this demo session.</p><form id="campaign-form"><label class="form-field">Campaign name<input name="name" required maxlength="35" placeholder="e.g. Autumn content plan"></label><label class="form-field">Focus<select name="focus"><option>Content optimization</option><option>AI search visibility</option><option>Local SEO</option></select></label><label class="form-field">Due date<input type="date" name="date" value="2026-10-15" required></label><button class="primary-button" type="submit">Create campaign</button></form>');document.querySelector('#campaign-form').onsubmit=e=>{e.preventDefault();const d=new FormData(e.target),name=d.get('name').trim();if(!name){toast('Enter a campaign name.');e.target.elements.name.focus();return}campaigns.push({name,sub:d.get('focus'),people:[12],count:'+0',progress:0,date:new Date(d.get('date')+'T12:00:00').toLocaleDateString('en-GB',{day:'numeric',month:'short',year:'numeric'}),score:'—'});document.querySelector('#search').value='';renderCampaigns();dialog.close();toast('Campaign added to this demo session.')}}
function downloadCSV(name,rows){const csv=rows.map(row=>row.map(v=>'"'+String(v).replaceAll('"','""')+'"').join(',')).join('\n');const url=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8;'}));const a=document.createElement('a');a.href=url;a.download=name.toLowerCase().replace(/[^a-z0-9]+/g,'-')+'-report.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Report downloaded.')}
document.querySelector('#close-dialog').onclick=()=>dialog.close();dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close()}});
document.querySelectorAll('[data-detail]').forEach(button=>button.onclick=()=>showDetails(button.dataset.detail));document.querySelectorAll('[data-nav]').forEach(button=>button.onclick=()=>{const nav=button.dataset.nav;if(nav==='overview'){dialog.close();window.scrollTo({top:0,behavior:'smooth'});return}if(nav==='new')return createCampaign();if(nav==='reports'){openDialog('Workspace reports',demo+lines([['Campaign report','CSV export'],['Reporting period','September 2026']])+'<button class="primary-button" id="export-all">Download campaign report</button>');document.querySelector('#export-all').onclick=()=>downloadCSV('uplift-ai',[['Campaign','Progress','Due date','Score'],...campaigns.map(c=>[c.name,c.progress,c.date,c.score])]);return}if(nav==='settings'){openDialog('Workspace settings','<p class="detail-intro">Appearance preferences are saved on this device.</p><label class="setting-row">Dark appearance<input type="checkbox" id="dark-check" '+(document.body.classList.contains('dark')?'checked':'')+'></label><div class="detail-line"><span>Workspace</span><strong>Uplift AI · Demo</strong></div>');document.querySelector('#dark-check').onchange=toggleTheme;return}showDetails(nav)});
function toggleTheme(){document.body.classList.toggle('dark');const dark=document.body.classList.contains('dark');document.querySelector('#theme').setAttribute('aria-label',dark?'Switch to light theme':'Switch to dark theme');try{localStorage.setItem('uplift-theme',dark?'dark':'light')}catch{}}try{if(localStorage.getItem('uplift-theme')==='dark')toggleTheme()}catch{}document.querySelector('#theme').onclick=toggleTheme;document.querySelector('.collapse').onclick=()=>document.querySelector('.sidebar').classList.toggle('expanded');
document.querySelector('#search').addEventListener('input',e=>renderCampaigns(e.target.value));document.addEventListener('keydown',e=>{if((e.metaKey||e.ctrlKey)&&e.key.toLowerCase()==='k'){e.preventDefault();document.querySelector('#search').focus()}});
document.querySelector('#share').onclick=()=>{openDialog('Share workspace', '<p class="detail-intro">Copy this draft’s link or download a report. Access to the hosted draft follows its sharing settings.</p><label class="form-field">Dashboard link<input id="share-url" readonly value="'+escapeHTML(location.href)+'"></label><button class="primary-button" id="copy-link">Copy link</button>');document.querySelector('#copy-link').onclick=async()=>{try{await navigator.clipboard.writeText(location.href);toast('Dashboard link copied.');dialog.close()}catch{document.querySelector('#share-url').select();toast('Select and copy the dashboard link.')}}};
